// Deliberately fake official-CLI protocol for harness transport tests. No model or auth.
use serde_json::{Value,json};
use std::io::Read;
fn main(){let a:Vec<String>=std::env::args().skip(1).collect();if a.iter().any(|x|x=="--help"){println!("--ignore-user-config --ignore-rules --output-schema --disable --ephemeral --sandbox --json --tools --strict-mcp-config --setting-sources --settings --disable-slash-commands --no-chrome --permission-mode --no-session-persistence --json-schema --output-format --effort --verbose --include-partial-messages");return;}let claude=a.iter().any(|s|s=="--print");if claude{println!("{}",json!({"type":"system","subtype":"init","tools":["StructuredOutput"],"mcp_servers":[],"permissionMode":"dontAsk"}));}let val=|key:&str|a.iter().position(|x|x==key).and_then(|i|a.get(i+1)).cloned().unwrap_or_default();if claude{assert_eq!(val("--tools"),"");assert_eq!(val("--permission-mode"),"dontAsk");assert_eq!(val("--mcp-config"),"{\"mcpServers\":{}}");}else{assert_eq!(val("--sandbox"),"read-only");assert!(a.windows(2).any(|w|w==["--disable","code_mode_host"]));assert!(a.iter().any(|x|x=="--ignore-user-config"));}let schema:Value=if claude{serde_json::from_str(&val("--json-schema")).unwrap()}else{serde_json::from_slice(&std::fs::read(val("--output-schema")).unwrap()).unwrap()};let mut input=String::new();std::io::stdin().read_to_string(&mut input).unwrap();assert!(!input.is_empty());if input.contains("fixture:pause"){std::thread::sleep(std::time::Duration::from_secs(2));}assert!(std::fs::read_dir(std::env::current_dir().unwrap()).unwrap().next().is_none());let mut output=if schema["properties"].get("rules").is_some(){json!({"rules":["Keep one readable focal action and a stable recognition hold."],"rationale":"Protocol fixture guidance only; not an artistic verdict or model inference."})}else{json!({"version":1,"name":"Harness protocol fixture, not AI art","width":512,"height":512,"fps":60,"durationFrames":120,"layers":[{"id":"fixture-dot","name":"Fixture dot","type":"ellipse","x":256,"y":256,"width":96,"height":96,"fill":"#1B6C80","stroke":"#1B6C80","strokeWidth":0,"rotation":0,"opacity":100,"scale":100,"cornerRadius":null,"tracks":{"x":[],"y":[],"scale":[],"rotation":[],"opacity":[]}}]})};if input.contains("fixture:self-approve"){output["approved"]=json!(true);}if claude{println!("{}",json!({"type":"result","subtype":"success","is_error":false,"permission_denials":[],"structured_output":output}));}else{println!("{}",json!({"type":"thread.started","thread_id":"harness-protocol-fixture"}));if input.contains("fixture:tool-event"){println!("{}",json!({"type":"item.completed","item":{"type":"command_execution","command":"not executed"}}));}println!("{}",json!({"type":"item.completed","item":{"type":"agent_message","text":output.to_string()}}));println!("{}",json!({"type":"turn.completed","usage":{}}));}}
